package com.example.simpleaccountant.ui.reports;import android.os.Bundle;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.dao.TransactionDao;import com.example.simpleaccountant.util.MoneyUtils;
public class ReportsActivity extends AppCompatActivity {@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_reports);TransactionDao d=new TransactionDao(this);((TextView)findViewById(R.id.tvReportIncome)).setText(MoneyUtils.format(d.getTotalIncome()));((TextView)findViewById(R.id.tvReportExpense)).setText(MoneyUtils.format(d.getTotalExpenses()));((TextView)findViewById(R.id.tvReportBalance)).setText(MoneyUtils.format(d.getBalance()));}}
